'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={lang:'fr',role:null,tab:'search',city:'Saint-Sauveur',sector:'all',radius:30,day:'today',customDate:'',skips:[],posts:[],connections:[],messages:{},profile:{employee:{sector:'Commerce',skills:['Service client','Caisse'],days:['mon','tue','wed'],rate:23},employer:{sector:'Restauration',skills:['Service client'],days:['mon','tue','wed'],rate:25}},plan:null,modal:null};
const tr=(fr,en)=>state.lang==='en'?en:fr;
const names={employee:['Camille — profil fictif','Camille — fictional profile'],employer:['Bistro Démo — entreprise fictive','Demo Bistro — fictional business']};
const categories=[['Commerce','🛍️','Retail'],['Restauration','🍽️','Food service'],['Entrepôt','📦','Warehouse'],['Construction','🏗️','Construction'],['Entretien','🧹','Cleaning'],['Événementiel','🎪','Events'],['Santé-soins','🩺','Health & care'],['Esthétique','💇','Beauty'],['Autre','✨','Other']];
const category=s=>{const c=categories.find(c=>c[0]===s);return c?c[1]+' '+tr(c[0],c[2]):esc(s)};
const fixtures=[
{id:'retail',sector:'Commerce',city:'Saint-Sauveur',km:4,rate:23,start:'12:00',end:'16:00',job:['Renfort en boutique','Retail support'],worker:['Vente et service client','Retail & customer service'],description:['Accueil des clients, rangement et aide à la caisse. Une équipe vous accompagne pendant le quart.','Welcome customers, organize displays and help at checkout. The team will guide you during the shift.'],skills:['Service client','Caisse']},
{id:'cafe',sector:'Restauration',city:'Sainte-Adèle',km:14,rate:25,start:'16:00',end:'21:00',job:['Coup de main pour le service','Evening service support'],worker:['Service en salle','Restaurant service'],description:['Mise en place, accueil et service en salle. Expérience appréciée; consignes et pauses à confirmer ensemble.','Set up, welcome guests and serve tables. Experience welcome; confirm instructions and breaks together.'],skills:['Accueil','Travail d’équipe']},
{id:'warehouse',sector:'Entrepôt',city:'Prévost',km:18,rate:24,start:'14:00',end:'18:00',job:['Préparation de commandes','Order preparation'],worker:['Manutention et commandes','Warehouse & orders'],description:['Préparer et emballer des colis légers. Formation d’accueil et équipements fournis dans cet exemple.','Prepare and pack light parcels. Orientation and equipment are provided in this example.'],skills:['Emballage','Inventaire']}
];
fixtures.forEach((p,i)=>{p.skillIds=[['service','checkout'],['table-service','food-safety'],['packing','inventory']][i];DispoStandards.seed('worker:'+p.id,[4.4,4.9,4.7][i],[12,22,8][i]);DispoStandards.seed('employer:'+p.id,[4.8,4.5,4.9][i],[18,10,25][i])});
const ln=pair=>pair[state.lang==='en'?1:0];
function toast(msg){const el=$('#toast');el.textContent=msg;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4200)}
function searchDate(){return state.day==='other'?state.customDate:AvailabilityDates.relativeDate(state.day)}
function dateLabel(day){if(day==='other')day=state.customDate;if(/^\d{4}-\d{2}-\d{2}$/.test(day||''))return new Date(day+'T12:00:00').toLocaleDateString(state.lang==='en'?'en-CA':'fr-CA',{day:'numeric',month:'long',year:'numeric'});return day==='tomorrow'?tr('Demain','Tomorrow'):day==='today'?tr('Aujourd’hui','Today'):tr('Choisis une date','Choose a date')}
function button(label,action,cls='primary'){return `<button class="${cls}" data-action="${action}">${label}</button>`}
function band(){return `<div class="demo-band"><strong>${tr('DÉMO INTERACTIVE','INTERACTIVE DEMO')}</strong>${tr('Profils fictifs · Actions simulées · Exploration sans compte · Aucun paiement réel','Fictional profiles · Simulated actions · Browse without an account · No real payments')}</div>`}
function language(){return `<div class="lang" aria-label="Langue / Language"><button data-lang="fr" class="${state.lang==='fr'?'on':''}" aria-pressed="${state.lang==='fr'}">FR</button><button data-lang="en" class="${state.lang==='en'?'on':''}" aria-pressed="${state.lang==='en'}">EN</button></div>`}
function home(){return `<div class="welcome-demo">${tr('Démo interactive · Profils et actions simulés','Interactive demo · Fictional profiles and simulated actions')}</div><header class="top welcome-top"><button class="brand" data-action="home" aria-label="${tr('Dispo — accueil','Dispo — home')}">dispo<i>●</i></button><div class="top-right">${language()}${activeAccount?accountToolbar():button(tr('Connexion','Log in'),'login','text-button')}</div></header><main class="welcome"><section class="welcome-hero"><p class="welcome-kicker">${tr('LE TRAVAIL, À TON RYTHME','WORK THAT FITS YOUR LIFE')}</p><h1>${tr('Du temps libre?','Got some free time?')}<br><span>${tr('Un coup de main à trouver?','Need an extra pair of hands?')}</span></h1><p class="welcome-intro">${tr('Des quarts de travail près de chez toi.<br>Du renfort quand ton entreprise en a besoin.','Find shifts close to home.<br>Find extra help when your business needs it.')}</p><div class="welcome-actions">${activeAccount!=='employer'?button(tr('Je veux travailler','I want to work')+' <span aria-hidden="true">↗</span>','enter-employee','primary worker-cta'):''}${activeAccount!=='employee'?button(tr('Je cherche du renfort','I need extra help')+' <span aria-hidden="true">↗</span>','enter-employer','primary employer-cta'):''}</div><p class="welcome-reassurance">${tr('Explore sans inscription · Gratuit pour les travailleurs','Browse without signing up · Free for workers')}</p></section><figure class="welcome-photo"><img src="images/cafe-team.jpg" alt="${tr('Une équipe prépare le service derrière le comptoir d’un café.','A team prepares service behind a café counter.')}" width="1600" height="1067" fetchpriority="high"><figcaption>${tr('Un peu de temps. Beaucoup de possibilités.','A little time. A lot of possibilities.')}</figcaption></figure><section id="how-it-works" class="welcome-how"><h2>${tr('Comment ça marche?','How does it work?')}</h2><ol><li><span>01</span>${tr('Publie','Post')}</li><li aria-hidden="true" class="step-arrow">→</li><li><span>02</span>${tr('Échange','Connect')}</li><li aria-hidden="true" class="step-arrow">→</li><li><span>03</span>${tr('Confirme ton quart','Confirm your shift')}</li></ol><p>${tr('Dispo vous met en relation. L’employeur paie directement le travailleur.','Dispo connects you. The employer pays the worker directly.')}</p></section><footer class="welcome-footer"><div class="welcome-links"><a href="#how-it-works">${tr('Comment ça marche','How it works')}</a>${button(tr('Aide et FAQ','Help & FAQ'),'home-help','text-button')}${activeAccount!=='employee'?button(tr('Forfaits employeurs','Employer plans'),'home-plans','text-button'):''}<a href="entreprises.html">${tr('Grandes entreprises','Enterprise')}</a></div><details><summary>${tr('À propos de cette démo','About this demo')}</summary><p>${tr('Les comptes, annonces, messages et avis sont simulés. Aucun paiement ni message réel. Les forfaits sont proposés à titre d’exemple.','Accounts, posts, messages and reviews are simulated. No real payments or messages. Plans are illustrative.')}</p>${button(tr('Réinitialiser la démo','Reset demo'),'reset','text-button')}<p class="photo-credit">Photo : <a href="https://unsplash.com/photos/people-working-near-desk-vNqE2R7hSoc" target="_blank" rel="noopener">Camille Chen / Unsplash</a></p></details></footer></main>`}
const title=()=>({search:tr(state.role==='employer'?'Trouvez votre prochain renfort.':'TROUVE TON QUART MAINTENANT',state.role==='employer'?'Find your next team member.':'FIND YOUR SHIFT NOW'),posts:tr(state.role==='employer'?'Vos besoins de personnel.':'Mon calendrier de disponibilités',state.role==='employer'?'Your staffing needs.':'My availability calendar'),connections:tr('Mes contacts et discussions','My contacts and chats'),payments:tr('Mes quarts confirmés','My confirmed shifts'),reviews:tr(state.role==='employer'?'Évaluer les travailleurs.':'Évaluer les employeurs.',state.role==='employer'?'Evaluate workers.':'Evaluate employers.'),profile:tr(state.role==='employer'?'Votre entreprise fictive.':'Ton profil fictif.',state.role==='employer'?'Your fictional business.':'Your fictional profile.'),help:tr('Aide et FAQ','Help & FAQ'),plans:tr('Forfaits employeurs','Employer plans')})[state.tab];
function roleConnections(){if(activeAccount!==state.role)return [];return state.connections.filter(c=>c.role===state.role)}
function nav(){const e=state.role==='employer';return [['search','⌕',tr(e?'Trouver du personnel':'TROUVE TON QUART MAINTENANT',e?'Find workers':'FIND YOUR SHIFT NOW')],['posts','◷',tr(e?'Mes besoins':'Offrir mes disponibilités',e?'My staffing needs':'Offer my availability')],['connections','⇄',tr('Mes contacts et discussions','My contacts and chats')],...(e?[['plans','◇',tr('Forfaits employeurs','Employer plans')]]:[]),['payments','✓',tr('Mes quarts confirmés','My confirmed shifts')],['reviews','☆',tr('Avis','Reviews')],['profile','◯',tr(e?'Mon entreprise':'Mon profil',e?'My business':'My profile')],['help','?',tr('Aide et FAQ','Help & FAQ')]].map(([id,icon,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}" aria-current="${state.tab===id?'page':'false'}"><span class="symbol">${icon}</span><span>${label}</span></button>`).join('')}
function render(){disposeSearchMap();document.documentElement.lang=state.lang;document.body.classList.toggle('employer-mode',state.role==='employer');const app=$('#app');if(!state.role){app.innerHTML=home()+(state.modal?modal():'');return}app.innerHTML=`${band()}<div class="shell"><aside><button class="brand" data-action="home">dispo<i>●</i></button><div class="workspace">${tr(state.role==='employer'?'ESPACE EMPLOYEUR':'ESPACE EMPLOYÉ',state.role==='employer'?'EMPLOYER WORKSPACE':'WORKER WORKSPACE')}</div><nav>${nav()}</nav><div class="aside-bottom">${tr('Dispo maintenant.<br>Du travail au bon moment.','Ready now.<br>Work at the right moment.')}</div></aside><div class="body"><header class="top"><span class="space-title">${tr(state.role==='employer'?'💼 Employeur · entreprise fictive':'◯ Employé · profil fictif',state.role==='employer'?'💼 Employer · fictional business':'◯ Worker · fictional profile')}</span><div class="top-right">${language()}${accountToolbar()}${button(tr('Accueil','Home'),'home','text-button')}</div></header><main><div class="page-heading"><div><div class="employee-label">${tr('EXPLORATION GUIDÉE','GUIDED EXPLORATION')}</div><h1>${title()}</h1><p>${tr('Cliquez, essayez et recommencez. Tout est simulé.','Click, try and start over. Everything is simulated.')}</p></div>${(state.role==='employer'&&(state.tab==='posts'||state.tab==='search'))?button(tr(state.role==='employer'?'+ Publier un besoin':'+ Offrir mes disponibilités',state.role==='employer'?'+ Post a staffing need':'+ Offer my availability'),'new-post'):''}</div>${pendingAction&&pendingAction.role===state.role?`<div class="notice">${tr('Une action est en attente. Votre préparation est conservée dans cet onglet.','An action is pending. Your preparation is saved in this tab.')} ${button(tr('Reprendre','Resume'),'resume','secondary')}</div>`:''}${page()}<footer>${tr('Dispo · Démonstration publique · Publications temporaires dans cet onglet · Modèles enregistrés dans ce navigateur.','Dispo · Public demonstration · Temporary posts in this tab · Templates saved in this browser.')}</footer></main></div></div>${state.modal?modal():''}`}
function page(){return ({search:searchPage,posts:postsPage,connections:connectionsPage,payments:paymentsPage,reviews:reviewsPage,profile:profilePage,help:helpPage,plans:plansPage}[state.tab]||searchPage)()}
function reputationKey(p){return (state.role==='employer'?'worker:':'employer:')+p.id}
function searchResults(){if(state.day==='other'&&(!state.customDate||state.customDate<AvailabilityDates.today()))return [];if(state.sector==='Autre'&&!state.otherSector?.trim())return [];const compatible=fixtures.filter(p=>(state.sector==='all'||p.sector===state.sector)&&p.km<=state.radius&&!state.skips.includes(state.role+':'+p.id)&&!roleConnections().some(c=>c.post.id===p.id));return DispoStandards.rank(compatible,reputationKey)}
function searchPage(){const list=searchResults(),p=list[0],e=state.role==='employer';return `<div class="search-layout"><section class="panel filters"><h2>${tr('Critères de recherche','Search criteria')}</h2>${e?`<label>${tr('Ville de départ','Starting city')}<select id="filter-city">${['Saint-Sauveur','Sainte-Adèle','Prévost'].map(c=>`<option ${state.city===c?'selected':''}>${c}</option>`).join('')}</select></label>`:cityControls()}<label>${tr('Rayon maximal','Maximum radius')} <strong>${state.radius} km</strong><input id="filter-radius" type="range" min="5" max="50" step="1" value="${state.radius}"></label><label>${tr('Quelle journée?','Which day?')}<select id="filter-day"><option value="today" ${state.day==='today'?'selected':''}>${tr('Aujourd’hui','Today')}</option><option value="tomorrow" ${state.day==='tomorrow'?'selected':''}>${tr('Demain','Tomorrow')}</option><option value="other" ${state.day==='other'?'selected':''}>${tr('Autre','Other')}</option></select></label>${state.day==='other'?`<label>${tr('Choisir une date','Choose a date')}<input id="filter-date" type="date" min="${AvailabilityDates.today()}" value="${esc(state.customDate||'')}" required></label>`:''}<label>${tr('Secteur','Category')}<select id="filter-sector"><option value="all">${tr('Tous les secteurs','All categories')}</option>${categories.map(c=>`<option value="${c[0]}" ${state.sector===c[0]?'selected':''}>${category(c[0])}</option>`).join('')}</select></label><small class="muted">${tr('Distances fictives autour de la ville choisie.','Fictional distances around the chosen city.')}</small></section><section>${!e?mapPanel():''}${DispoStandards.explanation(state.lang)}<div class="result-count">${list.length} ${tr(e?'profils fictifs disponibles':'offres fictives compatibles',e?'fictional workers available':'compatible fictional offers')}</div>${p?`<article class="card"><div class="card-top"><span class="pill">${tr('Exemple fictif','Fictional example')}</span><span class="muted">📍 ${p.km} km</span></div><div class="sector-icon">${categories.find(c=>c[0]===p.sector)[1]}</div><h2>${ln(e?p.worker:p.job)}</h2>${DispoStandards.badge(reputationKey(p),state.lang)}<p>${tr(e?'Travailleur · identité masquée':'Entreprise · identité masquée',e?'Worker · identity hidden':'Business · identity hidden')} · ${esc(state.city)}</p><div class="timing"><div><span class="muted">${dateLabel(state.day)}</span><strong>${p.start} – ${p.end}</strong></div><div class="rate">${p.rate} $<small>${tr('CA / h brut','CAD / h gross')}</small></div></div><p>${e?tr('Profil fictif avec expérience dans ce secteur. Compétences déclarées et disponibilité proposée pour tout le créneau.','Fictional profile with experience in this category. Self-declared skills and availability for the full time slot.'):ln(p.description)}</p>${DispoStandards.skillsSummary(p,state.lang)}<small class="muted">${tr('Contacts masqués avant déblocage employeur.','Contacts hidden before employer unlock.')}</small></article><div class="card-actions">${button(tr('Envoyer un message rapide','Send a quick message'),'interest:'+p.id,'secondary')}${button(tr('Passer','Pass'),'pass:'+p.id,'secondary')}${button(tr(e?'Simuler le déblocage →':'Ça m’intéresse →',e?'Simulate unlock →':'I’m interested →'),'connect:'+p.id)}</div>`:`<div class="panel empty"><h2>${state.day==='other'&&!state.customDate?tr('Choisis une date dans le calendrier','Choose a date in the calendar'):tr('Un autre créneau?','Another time slot?')}</h2><p>${tr('Élargis le rayon, change de secteur ou réaffiche les exemples.','Widen the radius, change categories or show examples again.')}</p>${button(tr('Réafficher les exemples','Show examples again'),'show-examples','secondary')}</div>`}</section></div>`}
const classicJobRoles=[['Commerce','Commis de commerce','Retail associate'],['Commerce','Caissier·ère','Cashier'],['Restauration','Plongeur·euse','Dishwasher'],['Restauration','Aide en cuisine','Kitchen assistant'],['Restauration','Serveur·euse','Server'],['Entrepôt','Manutentionnaire','Warehouse associate'],['Entretien','Préposé·e à l’entretien','Cleaning associate'],['Événementiel','Aide événementielle','Event assistant'],['Santé-soins','Soutien non clinique','Non-clinical support'],['Esthétique','Accueil en salon','Salon reception'],['Autre','Autre renfort','Other support'],['Construction','Aide sur chantier','Construction helper']];
function openClassicPlanner(post){const employee=state.role==='employee';DispoPlanner.open({lang:state.lang,key:'classic:'+state.role,employee,branches:employee?[state.city]:['Saint-Sauveur','Sainte-Adèle','Prévost'],roles:classicJobRoles.map((r,i)=>({key:String(i),other:r[0]==='Autre',label:tr(r[1],r[2])+' · '+category(r[0])})),prefill:post?{otherSector:post.otherSector||'',roleKey:String(post.jobKey||0),rate:post.rate,count:post.count||1,branches:[post.city||state.city],from:post.date||new Date().toLocaleDateString('en-CA'),to:post.date||new Date().toLocaleDateString('en-CA'),slots:[{start:post.start,end:post.end}],sameTeam:post.sameTeam||false}:undefined,onPublish(rows,meta){const publish=()=>{const series=(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2));let added=0;for(const r of rows){if(state.posts.some(p=>p.role===state.role&&String(p.jobKey)===r.roleKey&&(p.otherSector||'')===(r.otherSector||'')&&p.date===r.date&&p.city===r.city&&p.start===r.start&&p.end===r.end&&!p.closed))continue;state.posts.push({id:(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),series,role:state.role,sector:classicJobRoles[Number(r.roleKey)][0],jobKey:r.roleKey,otherSector:r.otherSector||'',date:r.date,city:r.city,start:r.start,end:r.end,rate:r.rate,count:r.count,sameTeam:r.sameTeam,closed:false});added++}state.modal=null;state.tab='posts';render();toast(tr(`${added} créneaux publiés. ${rows.length-added} doublons actifs ignorés.`,`${added} slots published. ${rows.length-added} active duplicates skipped.`))};if(needsAccount(publish))return;publish()}})}
function employeeAvailabilityPage(){
 const posts=state.posts.filter(p=>activeAccount==='employee'&&p.role==='employee');
 const {active,closed,expired}=AvailabilityDates.partition(posts);
 const label=active.length?tr('+ Offrir PLUS de disponibilités','+ Offer MORE availability'):tr('+ Offrir mes disponibilités','+ Offer my availability');
 return `<section class="availability-intro"><p>${tr('Choisis tes journées et tes heures. Tu restes libre d’accepter chaque offre.','Choose your days and hours. You remain free to accept each offer.')}</p>${button(label,'new-post','primary availability-cta')}</section>
 <section class="panel availability-current"><h2>${tr('Mes disponibilités en vigueur','My active availability')} <span class="pill">${active.length}</span></h2>${active.length?availabilityRows(active):`<div class="empty"><p>${tr('Aucune disponibilité en vigueur. Ajoute les jours et les heures où tu souhaites travailler.','No active availability. Add the days and hours when you want to work.')}</p></div>`}</section>
 ${closed.length?`<details class="panel availability-archive"><summary>${tr('Mes disponibilités clôturées','My closed availability')} (${closed.length})</summary>${availabilityRows(closed,'closed')}</details>`:''}
 <details class="panel availability-archive"><summary>${tr('Mes disponibilités expirées','My expired availability')} (${expired.length})</summary><p>${tr('Les dates passées sont classées ici automatiquement, dès le lendemain, selon la date de ton appareil.','Past dates are moved here automatically the next day, using your device’s date.')}</p>${expired.length?availabilityRows(expired,'expired'):`<p class="muted">${tr('Aucune disponibilité expirée pour le moment.','No expired availability yet.')}</p>`}</details>`;
}
function availabilityRows(posts,status='active'){
 const groups=[...new Set(posts.map(p=>p.series||p.id))];
 return groups.map(g=>{const list=posts.filter(p=>(p.series||p.id)===g).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start)),first=list[0];
 const heading=first.otherSector?esc(first.otherSector):first.jobKey!==undefined?tr(classicJobRoles[Number(first.jobKey)][1],classicJobRoles[Number(first.jobKey)][2]):category(first.sector);
 return `<article class="availability-series"><div class="row"><h3>${heading} · ${list.length} ${tr('créneau(x)','slot(s)')}</h3>${status==='active'&&list.length>1?button(tr('Clôturer ces disponibilités','Close these slots'),'close-series:'+g,'secondary'):''}</div>${list.map(p=>`<div class="row"><div><strong>${esc(p.date)} · ${esc(p.start)}–${esc(p.end)}</strong><p>${esc(p.city||state.city)} · ${p.rate} $/h ${tr('brut','gross')}</p></div><div class="row-actions">${status==='expired'?`<span class="pill">${tr('Expirée','Expired')}</span>`:status==='closed'?`<span class="pill">${tr('Plus disponible','Unavailable')}</span>`:''}${button(tr('Réutiliser / enregistrer','Reuse / save'),'reuse-post:'+p.id,'secondary')}${status==='active'?button(tr('Clôturer','Close'),'close:'+p.id,'secondary'):''}</div></div>`).join('')}</article>`}).join('');
}
function postsPage(){if(state.role==='employee')return employeeAvailabilityPage();const ps=state.posts.filter(p=>activeAccount===state.role&&p.role===state.role),groups=[...new Set(ps.map(p=>p.series||p.id))];return `<section class="panel"><div class="row"><div>${state.role==='employer'?`<h2>${tr('Postes, séries et modèles','Roles, series and templates')}</h2>`:''}<p>${state.role==='employee'?tr('Retrouve ici les jours et les heures que tu proposes.','Find the days and times you offer here.'):tr('Les modèles sont sauvegardés dans ce navigateur. Les publications restent temporaires dans cet onglet.','Templates are saved in this browser. Published entries remain temporary in this tab.')}</p></div>${state.role==='employer'?button(tr('Créer / charger un modèle','Create / load a template'),'new-post','secondary'):''}</div>${!ps.length?`<div class="empty"><p>${state.role==='employee'?tr('Aucune disponibilité proposée. Clique sur « Offrir mes disponibilités » pour commencer.','No availability posted. Select “Offer my availability” to get started.'):tr('Planifiez plusieurs dates, créneaux ou un mois complet.','Plan several dates, time slots or an entire month.')}</p></div>`:groups.map(g=>{let list=ps.filter(p=>(p.series||p.id)===g),first=list[0];return `<article style="border-top:1px solid #ddd;padding:20px 0"><div class="row"><div><h3>${first.otherSector?esc(first.otherSector):first.jobKey!==undefined?tr(classicJobRoles[Number(first.jobKey)][1],classicJobRoles[Number(first.jobKey)][2]):category(first.sector)} · ${list.length} ${tr('créneaux','slots')}</h3><p>${first.sameTeam?tr('Préférence : mêmes employés · acceptation requise pour chaque quart','Preference: same workers · each shift must be accepted'):tr('Chaque créneau peut être fermé séparément.','Each time slot can be closed separately.')}</p></div>${button(tr('Fermer toute la série','Close entire series'),'close-series:'+g,'secondary')}</div><details ${list.length<=4?'open':''}><summary>${tr('Voir les dates et gérer les créneaux','View dates and manage time slots')}</summary>${list.map(p=>`<div class="row"><div><strong>${esc(p.date||dateLabel(p.day))} · ${p.start}–${p.end}</strong><p>${esc(p.city||state.city)} · ${p.rate} $/h ${tr('brut','gross')}${state.role==='employer'?' · '+(p.count||1)+' '+tr('personne(s)','person(s)'):''}</p></div><div class="row-actions">${button(tr('Réutiliser / enregistrer','Reuse / save'),'reuse-post:'+p.id,'secondary')}${p.closed?`<span class="pill">✓ ${tr(state.role==='employer'?'Offre comblée':'Plus disponible',state.role==='employer'?'Filled':'Unavailable')}</span>`:button(tr(state.role==='employer'?'Marquer comblée':'Clôturer',state.role==='employer'?'Mark filled':'Close'),'close:'+p.id,'secondary')}</div></div>`).join('')}</details></article>`}).join('')}</section>`}
function connectionsPage(){const cs=roleConnections();return `<section class="panel"><h2>${tr('Un intérêt d’abord, une discussion ensuite','Start with interest, then chat')}</h2><p>${tr('Avant le match : envoie un message rapide depuis une annonce ou un profil. Il apparaît ici, en attente de réponse. Après acceptation : la discussion libre s’ouvre. Le quart se confirme ensuite, séparément.','Before matching: send a quick message from a listing or profile. It appears here awaiting a reply. After acceptance: free-form chat opens. Confirm the shift separately afterward.')}</p><p class="muted">${tr('Avant le déblocage, tu vois le profil ou l’annonce concernés, mais pas le nom ni les coordonnées. Les envois et réponses sont simulés.','Before unlocking, you see the relevant profile or listing, but not names or contact details. Sending and replies are simulated.')}</p>${!cs.length?`<div class="empty"><p>${tr('Aucune discussion pour le moment. Choisis « Envoyer un message rapide » sur une carte qui t’intéresse.','No chats yet. Choose “Send a quick message” on a card that interests you.')}</p>${button(tr('Voir les annonces et profils','Browse listings and profiles'),'goto-search')}</div>`:cs.map(c=>`<article class="chat-thread"><h3>${esc(ln(state.role==='employer'?c.post.worker:c.post.job))}</h3><p>${recipientLabel(c)} · ${esc(c.city)} · ${dateLabel(c.date)} · ${c.post.start}–${c.post.end}</p><span class="pill">${c.pending?tr('Intérêt envoyé · en attente de réponse','Interest sent · awaiting reply'):tr('Mise en contact simulée · discussion ouverte','Simulated match · chat open')}</span><div class="chat">${(state.messages[c.id]||[]).map(m=>`<div class="bubble ${m.mine?'mine':''}">${esc(m.body)}</div>`).join('')}</div>${c.pending?`<p>${tr('Ton message ne confirme ni un match ni un quart. Attends l’acceptation du destinataire pour discuter librement.','Your message does not confirm a match or a shift. Wait for the recipient to accept before chatting freely.')}</p>${button(tr('Simuler l’acceptation du destinataire','Simulate recipient acceptance'),'accept-interest:'+c.id,'secondary')}`:`<details><summary>${tr('Envoyer une phrase rapide','Send a quick phrase')}</summary>${quickChoices(c)}</details><form data-form="chat" data-id="${c.id}"><label>${tr('Ton message','Your message')}<input name="message" maxlength="350" required placeholder="${tr('Écris ici…','Write here…')}"></label><button class="primary">${tr('Envoyer (simulation)','Send (simulation)')}</button></form><div class="card-actions">${c.agreed?button(tr('Voir le quart confirmé','View confirmed shift'),'goto-payments','secondary'):button(tr('Confirmer ce quart','Confirm this shift'),'agreement:'+c.id,'secondary')}</div>`}</article>`).join('')}</section>`}
function paymentsPage(){
 const cs=roleConnections().filter(c=>!c.pending),employer=state.role==='employer';
 if(!cs.length)return `<section class="panel shifts-empty"><div class="shifts-empty-icon" aria-hidden="true">◷</div><h2>${tr('Aucun quart confirmé pour le moment','No confirmed shifts yet')}</h2><p>${tr(employer?'Lorsqu’un travailleur et toi confirmez un quart, tu le retrouves ici avec ses heures et son suivi.':'Une fois un quart convenu avec un employeur, tu le retrouves ici avec ses heures et son suivi.',employer?'Once you and a worker confirm a shift, its hours and progress appear here.':'Once you agree on a shift with an employer, its hours and progress appear here.')}</p><ol class="shift-guide"><li><strong>${tr(employer?'Trouve un travailleur':'Trouve un quart',employer?'Find a worker':'Find a shift')}</strong><span>${tr('Commence par la recherche.','Start with a search.')}</span></li><li><strong>${tr('Discute des détails','Discuss the details')}</strong><span>${tr('Lieu, heures, tâches et taux.','Location, hours, duties and rate.')}</span></li><li><strong>${tr('Confirme le quart','Confirm the shift')}</strong><span>${tr('Il apparaît ensuite ici.','It then appears here.')}</span></li></ol>${button(tr(employer?'Trouver du personnel':'Trouver un quart',employer?'Find workers':'Find a shift'),'goto-search','primary shifts-start')}<p class="shifts-empty-note">${tr('Tes échanges se trouvent dans « Mes contacts et discussions ».','Your conversations are in “My contacts and chats”.')}</p></section><p class="shift-payment-note">${tr('L’employeur paie directement le travailleur, hors de Dispo.','The employer pays the worker directly, outside Dispo.')}</p>`;
 const groups=[{fr:'À confirmer',en:'To confirm',status:'pending',items:cs.filter(c=>!c.agreed)},{fr:'À venir',en:'Upcoming',status:'upcoming',items:cs.filter(c=>c.agreed&&!c.completed)},{fr:'Terminés',en:'Completed',status:'completed',items:cs.filter(c=>c.completed)}];
 return `<p class="shifts-intro">${tr('Retrouve tes quarts et la prochaine étape pour chacun.','Find your shifts and the next step for each one.')}</p>${groups.filter(g=>g.items.length).map(g=>`<section class="shift-group"><h2>${tr(g.fr,g.en)} <span class="pill">${g.items.length}</span></h2>${g.items.map(c=>shiftCard(c,g.status)).join('')}</section>`).join('')}<p class="shift-payment-note">${tr('Aucun paiement dans Dispo. Les indications de paiement sont déclarées, sans vérification bancaire.','No payments through Dispo. Payment status is self-reported, without bank verification.')}</p><details class="panel shift-billing-details"><summary>${tr('Comment se passe le paiement?','How does payment work?')}</summary><p>${tr('L’employeur paie directement le travailleur, par virement Interac, comptant, par chèque ou par dépôt direct, selon leur entente. Les boutons ci-dessus enregistrent uniquement une déclaration dans cette démo : ils ne transfèrent aucun argent.','The employer pays the worker directly, by Interac transfer, cash, cheque or direct deposit, as agreed. The buttons above only record a statement in this demo: they do not transfer money.')}</p><p>${tr('Les taux sont bruts. Les retenues et documents de paie applicables restent à la charge des participants. Dispo ne calcule pas la paie.','Rates are gross. Participants remain responsible for applicable deductions and payroll documents. Dispo does not calculate payroll.')}</p></details>`;
}
function shiftCard(c,status){
 const employer=state.role==='employer';
 const next=status==='pending'?tr('Discute des conditions, puis confirme ce quart.','Discuss the terms, then confirm this shift.'):status==='upcoming'?tr('Tout est convenu. Reviens ici lorsque le quart est terminé.','Everything is agreed. Come back here when the shift is finished.'):tr('Le quart est terminé. Tu peux laisser ton avis.','The shift is complete. You can leave your review.');
 return `<article class="panel shift-card"><div class="shift-card-heading"><div><h3>${ln(c.post.job)}</h3><p>${employer?'Alex Démo':'Bistro Démo'} · ${esc(c.city||state.city)}</p></div><span class="pill">${tr(status==='pending'?'À confirmer':status==='upcoming'?'Confirmé':'Terminé',status==='pending'?'To confirm':status==='upcoming'?'Confirmed':'Completed')}</span></div><div class="shift-facts"><span>${esc(c.date||c.post.date||dateLabel(c.post.day||'today'))}</span><strong>${esc(c.post.start)}–${esc(c.post.end)}</strong><span>${c.post.rate} $ CA/h ${tr('brut','gross')}</span></div><p class="shift-next">${next}</p><div class="row-actions">${status==='pending'?button(tr('Confirmer ce quart','Confirm this shift'),'agreement:'+c.id):status==='upcoming'?button(tr('Marquer le quart terminé','Mark shift complete'),'complete:'+c.id):button(tr(c.review?'Voir mon avis':'Laisser un avis',c.review?'View my review':'Leave a review'),'goto-reviews')}${button(tr('Ouvrir mes discussions','Open my chats'),'goto-connections','secondary')}</div>${status==='completed'?`<div class="shift-payment"><h4>${tr('Suivi du paiement','Payment tracking')}</h4><p>${c.paid?tr(employer?'Paiement déclaré effectué · non vérifié par Dispo':'Paiement déclaré reçu · non vérifié par Dispo',employer?'Payment reported sent · not verified by Dispo':'Payment reported received · not verified by Dispo'):tr(employer?'Paiement non encore déclaré effectué.':'Réception du paiement non encore déclarée.',employer?'Payment has not been reported sent yet.':'Payment has not been reported received yet.')}</p>${!c.paid?button(tr(employer?'Indiquer que j’ai payé':'Indiquer que j’ai été payé',employer?'Report that I paid':'Report that I was paid'),'paid:'+c.id,'secondary'):''}</div>`:''}<small class="muted shift-demo">${tr('Démo : confirmations simulées.','Demo: simulated confirmations.')}</small></article>`;
}
function reviewsPage(){const e=state.role==='employer',cs=roleConnections().filter(c=>c.completed);return `<section class="panel">${DispoStandards.encourage(state.lang)}<p class="muted">${tr('Le paiement ne doit jamais dépendre d’un avis.','Payment must never depend on a review.')}</p>${!cs.length?`${DispoStandards.reviewPreview(e?'employee':'employer',state.lang)}<div class="empty"><p>${tr('Marque un quart terminé dans « Mes quarts confirmés » pour laisser ton avis.','Mark a shift complete in “My confirmed shifts” to leave your review.')}</p>${button(tr('Voir mes quarts confirmés','View my confirmed shifts'),'goto-payments','secondary')}</div>`:cs.map(c=>`<div class="row"><div><h3>${e?'Alex Démo':'Bistro Démo'}</h3><p>${ln(c.post.job)}</p>${c.review?`${DispoStandards.reviewSummary(c.review,e?'employee':'employer',state.lang)}<span class="pill">${tr('Avis fictif · démo uniquement','Fictional review · demo only')}</span>`:`<form data-form="review" data-id="${c.id}">${DispoStandards.reviewFields(e?'employee':'employer',state.lang)}<button class="primary">${tr('Enregistrer mon avis','Save my review')}</button></form>`}</div></div>`).join('')}<details><summary>${tr('Quand les avis deviennent-ils visibles?','When do reviews become visible?')}</summary><p>${tr('Dans cette démo, ton avis est affiché immédiatement et compte une seule fois dans le classement fictif du profil évalué. Il ne s’agit pas d’un avis public réel.','In this demo, your review appears immediately and counts once toward the reviewed profile’s demo ranking. It is not a real public review.')}</p></details></section>`}
function profilePage(){if(activeAccount!==state.role)return visitorProfile();const p=state.profile[state.role],e=state.role==='employer';return `<section class="panel"><span class="pill">${tr('Profil de démonstration prérempli','Prefilled demonstration profile')}</span><h2 style="margin-top:18px">${ln(names[state.role])}</h2><p>${tr('Utilisez uniquement des choix fictifs. Aucun compte réel n’est créé.','Use fictional choices only. No real account is created.')}</p><form data-form="profile">${contactFields(p,e)}${DispoStandards.skillsForm(p,e,state.lang)}${DispoStandards.encourage(state.lang)}<h3>${tr('Activité et disponibilités','Work and availability')}</h3><div class="form-grid"><label>${tr('Secteur','Category')}<select name="sector">${categories.map(c=>`<option value="${c[0]}" ${c[0]===p.sector?'selected':''}>${category(c[0])}</option>`).join('')}</select></label><label>${tr(e?'Taux brut offert ($ CA/h)':'Taux brut souhaité ($ CA/h)',e?'Offered gross rate (CAD/h)':'Desired gross rate (CAD/h)')}<input name="rate" type="number" min="1" max="1000" step="0.25" value="${p.rate}" required></label></div><label>${tr(e?'Jours habituels des besoins':'Mes disponibilités habituelles',e?'Usual staffing days':'My usual availability')}</label><div class="checks">${[['mon','Lundi','Monday'],['tue','Mardi','Tuesday'],['wed','Mercredi','Wednesday'],['thu','Jeudi','Thursday'],['fri','Vendredi','Friday'],['sat','Samedi','Saturday'],['sun','Dimanche','Sunday']].map(([id,fr,en])=>`<label class="check"><input type="checkbox" name="days" value="${id}" ${p.days.includes(id)?'checked':''}>${tr(fr,en)}</label>`).join('')}</div><p class="muted">${tr(e?'L’employeur vérifie les qualifications et confirme les conditions.':'Les qualifications sont déclarées, sans certification par Dispo. Tes disponibilités ne t’obligent pas à accepter une offre.',e?'Employers check qualifications and confirm working conditions.':'Qualifications are self-declared, not certified by Dispo. Availability does not require accepting an offer.')}</p><button class="primary">${tr('Enregistrer le profil fictif','Save fictional profile')}</button></form>${button(tr('Effacer mon profil','Delete my profile'),'delete-profile','profile-delete')}</section>${!e?verificationPanel():''}`}
function plansPage(){const items=[['free',0,'Découverte','Discovery','3 annonces actives','3 active posts'],['single',19,'Ponctuel','One-off','1 annonce débloquée','1 unlocked post'],['monthly',49,'Mensuel','Monthly','10 déblocages / mois','10 unlocks / month'],['quarterly',129,'3 mois','3 months','43 $ / mois','CA$43 / month'],['annual',449,'Annuel','Annual','37,42 $ / mois','CA$37.42 / month']];const details={free:[tr('Pour découvrir Dispo et afficher un besoin avant de choisir une formule payante.','Explore Dispo and post a staffing need before choosing a paid option.'),tr('Jusqu’à 3 annonces actives proposées. Le nom, les coordonnées et le lieu exact restent masqués avant le déblocage et la mise en relation.','Up to 3 active posts proposed. Names, contact details and exact locations remain hidden before unlocking and connecting.'),tr('Aucun accès direct aux contacts inclus. Un forfait payant ou un déblocage à la pièce est nécessaire pour poursuivre la mise en relation.','Direct contact access is not included. A paid plan or one-off unlock is needed to continue connecting.'),tr('Gratuit. Aucun achat nécessaire pour explorer cette démonstration.','Free. No purchase required to explore this demo.')],single:[tr('Pour un besoin occasionnel, sans choisir un abonnement de plusieurs mois.','For occasional staffing needs without choosing a multi-month subscription.'),tr('Déblocage proposé pour 1 annonce. Il permet de poursuivre les échanges avec les candidats intéressés selon leur accord.','Proposed unlock for 1 post. Continue conversations with interested applicants subject to their agreement.'),tr('Ce déblocage ne garantit ni candidature, ni présence, ni embauche. Les répétitions créent des annonces distinctes; leur couverture devra être confirmée dans les conditions commerciales.','An unlock does not guarantee applications, attendance or hiring. Repeats create separate posts; their coverage must be confirmed in the commercial terms.'),tr('19 $ CA à la pièce, avant taxes. Aucun renouvellement automatique dans la démo.','CA$19 per unlock, before taxes. No automatic renewal in the demo.')],monthly:[tr('Pour des besoins réguliers et un suivi mensuel.','For regular staffing needs and monthly planning.'),tr('10 déblocages d’annonces par mois proposés. Création de quarts, répétitions et modèles accessibles dans la démonstration.','10 post unlocks per month proposed. Shift creation, repeats and templates are available in the demo.'),tr('Le quota porte sur les déblocages, pas sur les modèles enregistrés. Report des crédits, dépassements et renouvellement restent à préciser avant la commercialisation.','The quota applies to unlocks, not saved templates. Credit rollover, overages and renewal terms remain to be defined before commercial launch.'),tr('49 $ CA par mois, avant taxes. Aucun prélèvement ni abonnement réel ici.','CA$49 per month, before taxes. No actual charge or subscription here.')],quarterly:[tr('Pour planifier les besoins sur une saison ou trois mois.','Plan staffing over a season or three months.'),tr('Formule de 3 mois proposée à 129 $ CA, soit 43 $ par mois en moyenne.','Proposed three-month option at CA$129, equivalent to CA$43 per month.'),tr('Le nombre de déblocages inclus, leur répartition et leur report restent à confirmer. Cette option ne signifie pas un accès illimité.','Included unlocks, their allocation and rollover remain to be confirmed. This option does not mean unlimited access.'),tr('129 $ CA pour 3 mois, avant taxes; l’équivalent mensuel n’est pas une mensualité distincte. Conditions de renouvellement et de résiliation à définir.','CA$129 for three months, before taxes; the monthly equivalent is not a separate monthly installment. Renewal and cancellation terms are to be defined.')],annual:[tr('Pour une entreprise qui prévoit des besoins tout au long de l’année.','For a business expecting staffing needs throughout the year.'),tr('Formule annuelle proposée à 449 $ CA, soit environ 37,42 $ par mois en moyenne.','Proposed annual option at CA$449, equivalent to approximately CA$37.42 per month.'),tr('Le nombre de déblocages inclus et leur cadence restent à confirmer. Aucun déblocage illimité n’est promis.','Included unlocks and their allocation schedule remain to be confirmed. Unlimited unlocks are not promised.'),tr('449 $ CA pour 12 mois, avant taxes; le prix mensuel affiché est un équivalent. Conditions de renouvellement et de résiliation à définir.','CA$449 for 12 months, before taxes; the displayed monthly price is an equivalent. Renewal and cancellation terms are to be defined.')]};return `<section class="panel"><div class="notice">${tr('Tarifs proposés avant taxes. Consultez les détails avant de choisir. Aucun achat ni abonnement réel n’est activé.','Proposed pre-tax prices. Review the details before choosing. No real purchase or subscription is activated.')}</div><div class="plans employer-plan-grid">${items.map(([id,price,fr,en,desc,dEn])=>`<article class="plan employer-plan"><h3>${tr(fr,en)}</h3><strong>${price?price+' $':tr('Gratuit','Free')}</strong><p>${tr(desc,dEn)}</p><details class="employer-plan-details"><summary>${tr('Voir les détails','View details')} · ${tr(fr,en)}</summary><div><h4>${tr('Pour quels besoins?','Who is it for?')}</h4><p>${details[id][0]}</p><h4>${tr('Ce qui est proposé','What is proposed')}</h4><p>${details[id][1]}</p><h4>${tr('Limites et fonctionnement','Limits and how it works')}</h4><p>${details[id][2]}</p><h4>${tr('Prix et durée','Price and duration')}</h4><p>${details[id][3]}</p><p class="muted">${tr('Les salaires sont payés directement par l’employeur. Dispo ne les encaisse pas.','Wages are paid directly by the employer. Dispo does not collect them.')}</p></div></details>${button(state.plan===id?tr('Choix simulé ✓','Simulated choice ✓'):tr('Essayer ce forfait','Try this plan'),'plan:'+id,'secondary')}</article>`).join('')}</div><details class="employer-plan-help"><summary>${tr('Qu’est-ce qu’un déblocage?','What is an unlock?')}</summary><p>${tr('C’est l’accès employeur aux contacts liés à une annonce, selon l’accord des participants. Publier un quart, enregistrer un modèle et débloquer une annonce sont des actions différentes. Dans cette démo, les déblocages et les quotas sont simulés, sans facturation.','It is employer access to contacts associated with a post, subject to participants’ agreement. Posting a shift, saving a template and unlocking a post are different actions. Unlocks and quotas in this demo are simulated, with no billing.')}</p></details><p class="muted" style="margin-top:20px">${tr('Les employés restent gratuits. Ouvrir les détails ne sélectionne aucun forfait.','Workers remain free. Opening details does not select a plan.')}</p></section>`}

function helpPage(){const e=state.role==='employer';const qs=e?[[tr('Comment publier un besoin?','How do I post a staffing need?'),tr('Ouvrez Mes besoins et choisissez le secteur, la journée, les heures et le taux brut. La publication est fictive dans cette démo.','Open My staffing needs and select a category, day, hours and gross rate. Publishing is fictional in this demo.')],[tr('Comment choisir un travailleur?','How do I select a worker?'),tr('Dans la recherche, simulez le déblocage d’un profil. Sa candidature acceptée et ses échanges deviennent visibles dans Mes contacts et discussions.','In search, simulate unlocking a profile. Its accepted application and conversation appear under My contacts and chats.')],[tr('Que faut-il confirmer avant le quart?','What should I confirm before a shift?'),tr('Le lieu exact, les tâches, les heures, les pauses, le taux, les risques, les qualifications et les équipements. Dispo n’affecte pas de personnel.','Exact location, duties, hours, breaks, rate, risks, qualifications and equipment. Dispo does not assign staff.')],[tr('Que dois-je évaluer?','What should I review?'),tr('Ponctualité, qualité du travail, communication et respect des consignes convenues.','Punctuality, work quality, communication and respect for agreed instructions.')]]:[[tr('Comment offrir quelques heures?','How do I offer a few hours?'),tr('Clique sur Offrir mes disponibilités. Choisis le secteur, la ou les journées, les heures et le taux souhaité.','Click Offer my availability. Select a category, one or more days, hours and desired rate.')],[tr('Suis-je obligé d’accepter une offre?','Am I required to accept an offer?'),tr('Non. Tu restes libre d’accepter ou de décliner. Confirme toujours les conditions avant le quart.','No. You can accept or decline. Always confirm conditions before the shift.')],[tr('Que faire si le travail ne correspond pas à l’annonce?','What if the work differs from the post?'),tr('Discute des différences avant d’accepter un changement, conserve les échanges et signale tout problème de sécurité à l’employeur. Dispo ne fournit pas de soutien d’urgence.','Discuss differences before accepting changes, keep messages and raise safety concerns with the employer. Dispo does not provide emergency support.')],[tr('Que dois-je évaluer?','What should I review?'),tr('La sécurité, la fidélité à l’annonce, l’accueil, la communication et le respect. Ne note pas un paiement qui n’a pas encore eu lieu.','Safety, accuracy of the post, welcome, communication and respect. Do not rate a payment that has not happened yet.')]];if(e)qs.push([tr('Quand est-il souhaitable de payer l’employé?','When is it best to pay the worker?'),tr('Comme le quart est ponctuel et le lien d’emploi temporaire, il est souhaitable de payer l’employé immédiatement après son quart, par virement Interac, comptant, par chèque ou par dépôt direct, selon l’entente convenue. Précisez ensemble le mode et le moment du paiement avant le début du quart.','Because the shift is occasional and the employment relationship temporary, prompt payment immediately after the shift is encouraged, by Interac transfer, cash, cheque or direct deposit, as agreed. Agree on the payment method and timing together before the shift begins.')]);qs.push([tr('Qui effectue le paiement?','Who makes the payment?'),tr('L’employeur paie directement par virement Interac, comptant, par chèque ou par dépôt direct, selon l’entente convenue avec l’employé. Aucun compte bancaire n’est connecté à Dispo. Dans cette démo, aucun argent ne circule.','The employer pays directly by Interac transfer, cash, cheque or direct deposit, as agreed with the worker. No bank account is connected to Dispo. No money moves in this demo.')],[tr('Est-ce la bêta réelle?','Is this the real beta?'),tr('Non. C’est une présentation interactive autonome avec données fictives. Les actions n’atteignent aucun vrai employeur, employé ou système de paiement. Fermer ou recharger cet onglet réinitialise la démo.','No. This is a standalone interactive presentation with fictional data. Actions do not reach real employers, workers or payment systems. Closing or reloading this tab resets the demo.')]);return `<section class="panel">${qs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`}
function modal(){const m=state.modal;if(m.type==='interest')return interestModal();if(['onboarding','register-role','login-role'].includes(m.type))return onboardingModal();let body='',heading='';if(m.type==='post'){heading=tr(state.role==='employer'?'Publier un besoin fictif':'Offrir une disponibilité fictive',state.role==='employer'?'Post a fictional staffing need':'Offer fictional availability');body=`<form data-form="post"><label>${tr('Secteur','Category')}<select name="sector">${categories.map(c=>`<option value="${c[0]}">${category(c[0])}</option>`).join('')}</select></label><label>${tr('Journée','Day')}<select name="day"><option value="today">${tr('Aujourd’hui','Today')}</option><option value="tomorrow">${tr('Demain','Tomorrow')}</option></select></label><div class="form-grid"><label>${tr('Début','Start')}<input name="start" type="time" value="12:00" required></label><label>${tr('Fin','End')}<input name="end" type="time" value="16:00" required></label></div><label>${tr('Taux brut ($ CA/h)','Gross rate (CAD/h)')}<input name="rate" type="number" min="1" max="1000" step="0.25" value="${state.profile[state.role].rate}" required></label><div class="notice">${tr('Aucune publication réelle. Aucun renseignement personnel demandé.','No real publication. No personal information requested.')}</div><button class="primary">${tr('Simuler la publication','Simulate publication')}</button></form>`}else if(m.type==='review'){heading=tr(state.role==='employer'?'Évaluer le travailleur fictif':'Évaluer l’employeur fictif',state.role==='employer'?'Review fictional worker':'Review fictional employer');body=`<form data-form="review" data-id="${m.id}">${DispoStandards.reviewFields(state.role==='employer'?'employee':'employer',state.lang)}<p class="muted">${tr('Avis de démonstration. Le paiement ne dépend jamais d’un avis.','Demo review. Payment never depends on a review.')}</p><button class="primary">${tr('Enregistrer mon avis','Save my review')}</button></form>`}return `<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${heading}</h2><button class="close" data-action="close-modal" aria-label="${tr('Fermer','Close')}">×</button></div>${body}</section></div>`}
function findConnection(id){return roleConnections().find(c=>c.id===id)}
function action(value){const [a,id]=value.split(':');if(a==='interest'){openInterest(id);return}if(a==='accept-interest'){const c=findConnection(id);if(!c?.pending)return;c.pending=false;state.messages[c.id].push({mine:false,body:tr('Réponse fictive : merci pour votre intérêt! Discutons des détails de ce quart.','Fictional reply: thank you for your interest! Let’s discuss this shift.')});render();return}if(a==='delete-profile'){deleteClassicProfile();return}if(a==='home-help'||a==='home-plans'){if(a==='home-plans'&&activeAccount==='employee')return;state.role=activeAccount||(a==='home-plans'?'employer':'employee');state.tab=a==='home-plans'?'plans':'help';render();window.scrollTo(0,0);return}if(a==='locate'){locateMunicipality();return}if(a==='register'||a==='login'){openOnboarding(a==='login');return}if(a==='register-role'||a==='login-role'){state.role=id;state.tab='profile';openOnboarding(a==='login-role');return}if(a==='resume'){state.role=pendingAction?.role||state.role;openOnboarding();return}if(a==='logout'){activeAccount=null;state.role=null;state.modal=null;onboardChallenge=null;render();return}if(a==='account-space'){state.role=activeAccount;state.tab='profile';render();return}if(a==='verify-send'){sendVerification(id);return}if(a==='home'){state.role=null;state.modal=null;render();return}if(a==='reset'){locationState.id='';locationState.message='';activeAccount=null;pendingAction=null;onboardChallenge=null;for(const p of Object.values(state.profile)){p.contacts={};p.verified={};p.registered=false}verificationPending=null;Object.assign(state,{role:null,tab:'search',skips:[],posts:[],connections:[],messages:{},plan:null,modal:null});render();toast(tr('Démo réinitialisée.','Demo reset.'));return}if(a==='enter-employee'||a==='enter-employer'){if(activeAccount&&activeAccount!==a.slice(6)){toast(tr('Déconnectez-vous pour explorer l’autre rôle.','Log out to explore the other role.'));return}state.role=a.slice(6);state.tab='search';render();window.scrollTo(0,0);return}if(a.startsWith('goto-')){state.tab=a.slice(5);render();return}if(a==='new-post'){openClassicPlanner();return}if(a==='reuse-post'){openClassicPlanner(state.posts.find(p=>p.id===id&&p.role===state.role));return}if(a==='close-series'){state.posts.filter(p=>(p.series||p.id)===id&&p.role===state.role&&(state.role!=='employee'||(!p.closed&&!AvailabilityDates.isExpired(p)))).forEach(p=>p.closed=true);render();return}if(a==='close-modal'){state.modal=null;render();return}if(a==='pass'){state.skips.push(state.role+':'+id);render();return}if(a==='show-examples'){state.skips=state.skips.filter(s=>!s.startsWith(state.role+':'));state.sector='all';state.radius=30;render();return}if(a==='connect'){if(!searchDate()||searchDate()<AvailabilityDates.today())return;if(needsAccount(()=>action(value),true))return;const p=fixtures.find(p=>p.id===id);if(!p)return;state.connections.push({id:(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),role:state.role,post:p,date:searchDate(),city:state.city,agreed:false,completed:false,paid:false});state.tab='connections';render();toast(tr('Candidature, déblocage et acceptation simulés.','Application, unlock and acceptance simulated.'));return}if(a==='close'){const p=state.posts.find(p=>p.id===id&&p.role===state.role);if(p)p.closed=true;render();return}if(a==='agreement'){const c=findConnection(id);if(c&&!c.pending)c.agreed=true;state.tab='payments';render();toast(tr('Entente acceptée par les deux parties fictives.','Agreement accepted by both fictional participants.'));return}if(a==='complete'){const c=findConnection(id);if(c&&c.agreed)c.completed=true;render();return}if(a==='paid'){const c=findConnection(id);if(c&&c.completed)c.paid=true;render();toast(tr('Confirmation simulée. Aucun transfert effectué.','Simulated confirmation. No transfer made.'));return}if(a==='review'){const c=findConnection(id);if(!c?.completed)return;state.modal={type:'review',id};render();focusModal();return}if(a==='plan'){if(needsAccount(()=>action(value)))return;state.plan=id;render();toast(tr('Choix simulé. Aucun achat effectué.','Simulated choice. No purchase made.'))}}
let modalReturnFocus=null;function focusModal(){requestAnimationFrame(()=>$('.modal input,.modal select,.modal textarea,.modal button')?.focus())}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lang){state.lang=b.dataset.lang;render();return}if(b.dataset.tab){state.tab=b.dataset.tab;render();return}if(b.dataset.action){if(b.dataset.action==='new-post'||b.dataset.action.startsWith('review:'))modalReturnFocus=b;action(b.dataset.action)}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='filter-municipality'){const m=qcSorted.find(m=>municipalityLabel(m)===el.value)||qcSorted.filter(m=>m.name.toLocaleLowerCase()===el.value.trim().toLocaleLowerCase()).filter((m,i,a)=>a.length===1)[0];if(el.value&&!m){el.setCustomValidity(tr('Choisissez une ville dans les suggestions.','Choose a city from the suggestions.'));el.reportValidity();return}el.setCustomValidity('');locationState.id=m?.id||'';state.city=m?.name||'';locationState.message=''}else if(el.id==='filter-sector'){state.sector=el.value;state.otherSector=''}else if(el.id==='filter-radius')state.radius=Number(el.value);else if(el.id==='filter-city')state.city=el.value;else if(el.id==='filter-day'){state.day=el.value}else if(el.id==='filter-date'){if(!el.checkValidity()){el.reportValidity();return}state.customDate=el.value}else return;render();if(el.id==='filter-day'&&state.day==='other'){const calendar=document.getElementById('filter-date');calendar?.focus();try{calendar?.showPicker()}catch{}}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const f=new FormData(form),type=form.dataset.form;if(type.startsWith('onboard-')){onboardingSubmit(type,f);return}if(type==='verify'){checkVerification(f);return}if(type==='post'){if(f.get('start')>=f.get('end')){toast(tr('L’heure de fin doit suivre le début.','End time must follow start time.'));return}state.posts.push({id:(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),role:state.role,sector:f.get('sector'),otherSector:String(f.get('otherSector')||'').trim(),day:f.get('day'),date:AvailabilityDates.relativeDate(f.get('day')),start:f.get('start'),end:f.get('end'),rate:Number(f.get('rate')),closed:false});state.modal=null;state.tab='posts';render();toast(tr('Annonce fictive publiée dans cette démo.','Fictional post published in this demo.'))}if(type==='profile'){let skills;try{skills=DispoStandards.readSkills(f)}catch(error){toast(skillError(error));return}if(!saveContactFields(f))return;Object.assign(state.profile[state.role],skills);state.profile[state.role]={...state.profile[state.role],sector:f.get('sector'),otherSector:String(f.get('otherSector')||'').trim(),rate:Number(f.get('rate')),days:f.getAll('days')};render();toast(tr('Profil fictif enregistré pour cet onglet.','Fictional profile saved for this tab.'))}if(type==='chat'){const c=findConnection(form.dataset.id);if(!c||c.pending)return;const body=String(f.get('message')).trim();if(!body)return;state.messages[c.id]||=[];state.messages[c.id].push({mine:true,body},{mine:false,body:tr('Réponse fictive : merci! Les conditions de cet exemple nous conviennent. Confirme l’entente pour continuer la démonstration.','Fictional reply: thank you! The example terms work for us. Confirm the agreement to continue the demonstration.')});render()}if(type==='review'){const c=findConnection(form.dataset.id);if(!c?.completed||c.review)return;let review;try{review=DispoStandards.readReview(f,state.role==='employer'?'employee':'employer')}catch{toast(tr('Choisis une note de 1 à 5 étoiles.','Choose a rating from 1 to 5 stars.'));return}c.review=review;DispoStandards.addReview(reputationKey(c.post),c.id,review);state.modal=null;render();toast(tr('Avis fictif enregistré. Le classement de démonstration est actualisé.','Demo review saved. Demo ranking updated.'))}});
document.addEventListener('keydown',e=>{if(!state.modal)return;if(e.key==='Escape'){state.modal=null;render();return}if(e.key==='Tab'){const els=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea')].filter(el=>!el.disabled),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});

let verificationPending=null;
const contactNames=['firstName','lastName','companyName','legalName','registration','contactRole','email','phone','extension','website','street','unit','city','province','postal','country'];
function contactFields(p,employer){const c=p.contacts||{};function field(n,fr,en,type='text',required=false,placeholder=''){return `<label>${tr(fr,en)}${required?' *':''}<input name="${n}" type="${type}" maxlength="${n==='website'?200:120}" value="${esc(c[n]||'')}" ${required?'required':''} placeholder="${esc(placeholder)}" autocomplete="off"></label>`}return `<h3>${tr(employer?'Coordonnées de l’entreprise':'Mes coordonnées privées',employer?'Business contact details':'My private contact details')}</h3><div class="notice">${tr('Démo : entrez uniquement des coordonnées fictives. Ces champs ne sont pas ajoutés aux annonces publiques. La recherche d’adresse utilise Photon.','Demo: enter fictional contact details only. These fields are not added to public posts. Address search uses Photon.')}</div><p class="muted">* ${tr('Champs obligatoires','Required fields')}</p><div class="form-grid">${employer?field('companyName','Nom commercial','Business name','text',true)+field('legalName','Raison sociale','Legal business name','text',true)+field('registration','NEQ / numéro d’entreprise (facultatif)','Business registration number (optional)')+field('website','Site web (facultatif)','Website (optional)','url',false,'https://exemple.ca'):''}${field('firstName',employer?'Prénom du responsable':'Prénom',employer?'Contact first name':'First name','text',true)}${field('lastName',employer?'Nom du responsable':'Nom de famille',employer?'Contact last name':'Last name','text',true)}${employer?field('contactRole','Fonction du responsable','Contact job title','text',true):''}${field('email','Adresse courriel','Email address','email',true,'alex@example.com')}${field('phone','Téléphone (10 chiffres, avec ou sans tirets)','Phone (10 digits, with or without hyphens)','tel',false,'450-555-1234')}${employer?field('extension','Poste téléphonique (facultatif)','Extension (optional)'):''}${field('street','Numéro et rue','Street address','text',employer)}${field('unit','Appartement / bureau (facultatif)','Apartment / suite (optional)')}${field('city','Ville / municipalité','City / municipality','text',true)}${field('province','Province / État / région','Province / state / region','text',employer)}${field('postal','Code postal','Postal / ZIP code','text',employer)}${field('country','Pays','Country','text',employer)}</div><p class="muted">${tr('Les coordonnées et l’adresse exacte sont distinctes du profil public. Aucun document d’identité ni numéro d’assurance sociale n’est demandé ici.','Contact details and exact address are separate from the public profile. No identity document or social insurance number is requested here.')}</p>`}
function normalizePhone(s){return DispoStandards.phone(s)??String(s).trim()}
function saveContactFields(f){const p=state.profile[state.role],old=p.contacts||{},next={};for(const n of contactNames)next[n]=String(f.get(n)||'').trim();next.email=next.email.toLowerCase();next.phone=normalizePhone(next.phone);if(next.phone&&!DispoStandards.phone(next.phone)){toast(tr('Entre 10 chiffres, par exemple 4505551234 ou 450-555-1234.','Enter 10 digits, for example 4505551234 or 450-555-1234.'));return false}p.verified||={};if(old.email!==next.email){delete p.verified.email;if(verificationPending?.kind==='email')verificationPending=null}if(old.phone!==next.phone){delete p.verified.phone;if(verificationPending?.kind==='phone')verificationPending=null}p.contacts=next;return true}
function verificationPanel(){const p=state.profile.employee,c=p.contacts||{},v=p.verified||{},pending=verificationPending;return `<section class="panel" style="margin-top:22px"><h2>${tr('Vérification du travailleur','Worker verification')}</h2><p>${tr('Première étape : confirmer l’accès au téléphone et/ou au courriel. Cela ne prouve pas à lui seul l’identité légale ni les qualifications.','First step: confirm access to a phone and/or email. This alone does not establish legal identity or qualifications.')}</p><div class="notice">${tr('Simulation uniquement : aucun SMS, courriel ou appel réel. Les badges ci-dessous sont fictifs. Enregistrez vos coordonnées avant de tester.','Simulation only: no real SMS, email or phone call. Badges below are fictional. Save your contact details before testing.')}</div><div class="row"><div><h3>${tr('Courriel','Email')}</h3><p>${esc(c.email||tr('Non renseigné','Not provided'))}</p><span class="pill">${v.email===c.email&&c.email?tr('✓ Courriel confirmé — simulation','✓ Email confirmed — simulation'):tr('Non confirmé','Not confirmed')}</span></div><button class="secondary" data-action="verify-send:email" ${!c.email?'disabled':''}>${tr('Simuler un code par courriel','Simulate email code')}</button></div><div class="row"><div><h3>${tr('Téléphone','Phone')}</h3><p>${esc(c.phone||tr('Non renseigné','Not provided'))}</p><span class="pill">${v.phone===c.phone&&c.phone?tr('✓ Téléphone confirmé — simulation','✓ Phone confirmed — simulation'):tr('Non confirmé','Not confirmed')}</span></div><div class="row-actions"><button class="secondary" data-action="verify-send:sms" ${!c.phone?'disabled':''}>${tr('Simuler un SMS','Simulate SMS')}</button><button class="secondary" data-action="verify-send:call" ${!c.phone?'disabled':''}>${tr('Simuler un appel vocal','Simulate voice call')}</button></div></div>${pending?`<form data-form="verify" class="verification-code"><h3>${tr('Saisir le code de démonstration','Enter the demo code')}</h3><p>${tr('Canal','Channel')} : ${pending.method==='email'?tr('courriel','email'):pending.method==='sms'?'SMS':tr('appel vocal','voice call')} · ${esc(pending.target)}</p><div class="notice">${tr('Code fictif affiché ici pour le test','Fictional code shown here for testing')} : <strong>${pending.code}</strong><br>${tr('Valide 5 minutes · 5 essais maximum · Un seul code actif à la fois.','Valid for 5 minutes · Maximum 5 attempts · One active code at a time.')}</div><label>${tr('Code à 6 chiffres','6-digit code')}<input name="code" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autocomplete="off"></label><button class="primary">${tr('Valider le code simulé','Validate simulated code')}</button></form>`:''}<p class="muted">${tr('Modifier le téléphone ou le courriel enregistré annule la confirmation correspondante. Pour un usage réel, il faudra connecter un service d’envoi et valider les codes côté serveur.','Changing a saved phone or email clears its confirmation. Real use requires a delivery provider and server-side code validation.')}</p></section>`}
function sendVerification(method){const p=state.profile.employee,c=p.contacts||{},kind=method==='email'?'email':'phone';if(state.role!=='employee'||!c[kind])return;const current=document.querySelector('[data-form="profile"]');if(current&&(current.elements.email.value.trim().toLowerCase()!==c.email||normalizePhone(current.elements.phone.value.trim())!==c.phone)){toast(tr('Enregistrez vos nouvelles coordonnées avant de les vérifier.','Save your updated contact details before verifying them.'));return}if(verificationPending&&Date.now()-verificationPending.sent<30000){toast(tr('Attendez 30 secondes avant de demander un autre code simulé.','Wait 30 seconds before requesting another simulated code.'));return}const bytes=new Uint32Array(1);crypto.getRandomValues(bytes);verificationPending={method,kind,target:c[kind],code:String(100000+bytes[0]%900000),sent:Date.now(),attempts:0};render();toast(tr('Code simulé affiché sous les options de vérification. Aucun envoi réel.','Simulated code shown below verification options. Nothing was sent.'))}
function checkVerification(f){const p=verificationPending;if(state.role!=='employee'||!p)return;const profile=state.profile.employee;if(Date.now()-p.sent>300000||profile.contacts?.[p.kind]!==p.target){verificationPending=null;render();toast(tr('Code expiré. Demandez un nouveau code simulé.','Code expired. Request a new simulated code.'));return}p.attempts++;if(String(f.get('code'))!==p.code){if(p.attempts>=5){verificationPending=null;render()}toast(tr('Code incorrect.','Incorrect code.')+' '+(p.attempts>=5?tr('Demandez un nouveau code.','Request a new code.'):tr(`${5-p.attempts} essais restants.`,`${5-p.attempts} attempts left.`)));return}profile.verified||={};profile.verified[p.kind]=p.target;verificationPending=null;render();toast(tr('Coordonnée confirmée dans la simulation uniquement.','Contact confirmed in the simulation only.'))}
render();

// Reclassify at a date change without interrupting an open form.
let availabilityRenderedDate=AvailabilityDates.today();
function refreshAvailabilityDate(){
 const today=AvailabilityDates.today();
 if(today===availabilityRenderedDate||state.modal||document.querySelector('.ds-overlay'))return;
 availabilityRenderedDate=today;
 if(state.role==='employee'&&state.tab==='posts')render();
}
setInterval(refreshAvailabilityDate,30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshAvailabilityDate()});
window.addEventListener('focus',refreshAvailabilityDate);

function skillError(error){return error.message==='licence'?tr('Choisis au moins une classe de permis.','Choose at least one licence class.'):tr('Précise ton autre compétence.','Specify your other skill.')}
function deleteClassicProfile(){const role=state.role;if(activeAccount!==role)return;DispoStandards.confirmDelete(tr('Le profil, les coordonnées, les publications, les échanges et les modèles enregistrés de cet espace seront effacés. L’autre espace ne sera pas touché.','This workspace’s profile, contact details, posts, conversations and saved templates will be cleared. The other workspace will not be affected.'),()=>{
 localStorage.removeItem('dispo-post-templates-v1:classic:'+role);
 const ids=state.connections.filter(c=>c.role===role).map(c=>c.id);for(const id of ids)delete state.messages[id];
 state.connections=state.connections.filter(c=>c.role!==role);state.posts=state.posts.filter(p=>p.role!==role);state.skips=state.skips.filter(s=>!s.startsWith(role+':'));
 state.profile[role]={sector:role==='employee'?'Commerce':'Restauration',skills:[],skillIds:[],licenceClasses:[],days:[],rate:24,contacts:{},verified:{},registered:false};if(role==='employer')state.plan=null;
 pendingAction=null;onboardChallenge=null;verificationPending=null;activeAccount=null;state.modal=null;state.role=null;state.tab='search';render();toast(tr('Profil de démonstration effacé.','Demo profile deleted.'));
},state.lang)}

function quickPhrases(){return state.role==='employee'?[
 tr('Bonjour! Votre poste m’intéresse beaucoup. Seriez-vous disponible pour échanger sur les tâches et vos attentes?','Hello! I’m very interested in your listing. Could we discuss the duties and your expectations?'),
 tr('Bonjour! Je souhaite vous proposer ma candidature pour ce quart. Mon profil présente mes compétences; je serais heureux d’en discuter avec vous.','Hello! I’d like to apply for this shift. My profile lists my skills, and I’d be happy to discuss them with you.'),
 tr('Bonjour! Avant de confirmer mon intérêt, pourriez-vous me préciser les tâches et les conditions de ce quart?','Hello! Before confirming my interest, could you share more about the duties and conditions for this shift?'),
 tr('Bonjour! J’aimerais rejoindre votre équipe pour ce quart. Si mon profil correspond à vos besoins, échangeons ici!','Hello! I’d like to join your team for this shift. If my profile fits your needs, let’s chat here!')
 ]:[
 tr('Bonjour! Votre profil nous intéresse pour un renfort ponctuel. Seriez-vous disponible pour en discuter ici?','Hello! Your profile interests us for temporary support. Would you be available to discuss it here?'),
 tr('Bonjour! Vos compétences semblent correspondre à nos besoins. Nous aimerions vous présenter les tâches et les conditions du quart.','Hello! Your skills seem to fit our needs. We’d like to share the shift duties and conditions with you.'),
 tr('Bonjour! Nous aimerions connaître votre intérêt et confirmer vos disponibilités avant de vous proposer un quart. Échangeons ici!','Hello! We’d like to hear about your interest and confirm your availability before offering a shift. Let’s chat here!'),
 tr('Bonjour! Nous serions heureux d’en savoir plus sur votre expérience. Si notre proposition vous intéresse, discutons des détails dans cette messagerie.','Hello! We’d be happy to learn more about your experience. If our proposal interests you, let’s discuss the details here.')
 ];}
function recipientLabel(c){return c.pending?tr(state.role==='employer'?'Destinataire : profil employé masqué':'Destinataire : employeur de cette annonce',state.role==='employer'?'Recipient: hidden worker profile':'Recipient: employer behind this listing')+' · '+esc(c.post.id):tr(state.role==='employer'?'Alex Démo · profil fictif':'Bistro Démo · entreprise fictive',state.role==='employer'?'Alex Demo · fictional profile':'Demo Bistro · fictional business');}
function quickChoices(c){return `<fieldset class="quick-choices"><legend>${tr('Coche une phrase pour l’envoyer immédiatement (simulation)','Select a phrase to send it immediately (simulation)')}</legend>${quickPhrases().map((text,i)=>`<label><input type="checkbox" data-quick-message="${i}" data-thread="${esc(c?.id||'')}" ${c?.quickSent?.includes(i)?'checked disabled':''}><span>${esc(text)}</span></label>`).join('')}</fieldset>`}
function openInterest(id){const p=fixtures.find(p=>p.id===id),date=searchDate();if(!p||!date||date<AvailabilityDates.today())return;if(needsAccount(()=>openInterest(id),true))return;const existing=roleConnections().find(c=>c.post.id===id);if(existing){state.tab='connections';render();return}state.modal={type:'interest',post:p,date,city:state.city,role:state.role};render();focusModal()}
function interestModal(){const m=state.modal;return `<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${tr('Manifester mon intérêt','Express my interest')}</h2>${button('×','close-modal','close')}</div><p>${recipientLabel({...m,pending:true})}</p><h3>${esc(ln(state.role==='employer'?m.post.worker:m.post.job))}</h3><p>${esc(m.city)} · ${dateLabel(m.date)} · ${m.post.start}–${m.post.end}</p><p>${tr('Un seul message d’introduction avant acceptation. L’identité reste masquée; aucun quart n’est confirmé.','One introduction message before acceptance. Identity remains hidden; no shift is confirmed.')}</p>${quickChoices()}<small>${tr('Démo : aucun destinataire réel ni notification envoyée.','Demo: no real recipient or notification.')}</small></section></div>`}
function sendQuickMessage(index,threadId){if(!Number.isInteger(index)||index<0||index>3||activeAccount!==state.role)return;let c=threadId?findConnection(threadId):null;if(threadId&&(!c||c.pending||c.quickSent?.includes(index)))return;if(!threadId){const m=state.modal;if(m?.type!=='interest'||m.role!==state.role||m.date<AvailabilityDates.today()||roleConnections().some(c=>c.post.id===m.post.id))return;c={id:crypto.randomUUID(),role:state.role,post:m.post,date:m.date,city:m.city,pending:true,agreed:false,completed:false,paid:false};state.connections.push(c)}c.quickSent||=[];c.quickSent.push(index);state.messages[c.id]||=[];state.messages[c.id].push({mine:true,body:quickPhrases()[index]});state.modal=null;state.tab='connections';render();toast(tr('Message rapide enregistré (simulation).','Quick message saved (simulation).'))}
document.addEventListener('change',e=>{if(e.target.matches('[data-quick-message]')&&e.target.checked)sendQuickMessage(Number(e.target.dataset.quickMessage),e.target.dataset.thread)});
